[611] = { en = "The Curse of the Tides", tier = 3,
  t = "De vloek van de getijden",
  d = "Dus je zoekt een soort altaar? Nou, ik ben geen expert in trollenruïnes, zoals mijn vader. Maar ik heb gehoord over een gezonken trollenstad bij dat eiland dat je zoekt. Misschien moet je het daar proberen.$b$bJe hebt mijn mes voor me teruggehaald, dus ik denk dat je het mag lenen... maar ik wil het terug als je klaar bent!",
  o = "Vernietig het Altar of the Tides met Catelyn's Blade, dood Gazban en breng de Stone of the Tides en Catelyn's Blade terug naar Baron Revilgaz.",
  p = "Heb je de Stone of the Tides voor me teruggehaald, $N? Ik heb al een plek vrijgemaakt en er een mooie standaard voor gekocht.",
  c = "Geweldig! De Stone of Tides! Hij krijgt een belangrijke plek in mijn verzameling oude trollenvoorwerpen. Zag je dat het bijna lijkt alsof er een getij gevangen zit in het oppervlak? Prachtig!",
  g = { {"getijden", "tides (getij)"}, {"altaar", "altar"}, {"trollenruïnes", "troll ruins (ruïne)"}, {"gezonken", "sunken (zinken)"}, {"lenen", "to borrow, to lend"}, {"teruggehaald", "got back, retrieved (terughalen)"}, {"vrijgemaakt", "cleared out (vrijmaken)"}, {"standaard", "stand"}, {"verzameling", "collection"}, {"trollenvoorwerpen", "troll artifacts (voorwerp = object)"}, {"gevangen", "trapped, captured"}, {"oppervlak", "surface"}, {"Prachtig", "magnificent, beautiful"} },
