[196] = { en = "Raptor Mastery", tier = 3,
  t = "Meester van de raptors",
  d = "Eens kijken hoe je deze volgende uitdaging aanpakt. Er leeft daar een sluw soort raptor. Wij noemen ze Jungle Stalkers. Ze zijn veel moeilijker op te sporen en te doden dan de andere soorten waarop je je geluk al hebt beproefd. Dood 10 Jungle Stalkers, dan geef ik je een tip voor de beste jacht tot nu toe.",
  o = "Hemet Nesingwary wil dat je 10 Jungle Stalkers doodt.",
  p = "Bah! Wat sta je hier nou rond te hangen, $n! Een echte grootwildjager geeft nooit op als hij zijn prooi in het vizier heeft. Die Jungle Stalkers komen echt niet naar dit kampvuur rennen om zich erin te gooien. Gekke $gkerel:meid;.",
  c = "Ho ho!! Hier hebben we een echte raptordoder! Goed gedaan, $gbeste kerel:mooie dame;!",
  g = { {"uitdaging", "challenge"}, {"aanpakt", "handle, tackle (aanpakken)"}, {"sluw", "cagey, sly"}, {"soort", "kind, breed"}, {"op te sporen", "to track down (opsporen)"}, {"beproefd", "tried (beproeven; je geluk beproeven = try your luck)"}, {"rond te hangen", "to stand around (rondhangen)"}, {"grootwildjager", "big game hunter"}, {"prooi", "prey"}, {"in het vizier", "in his sights (vizier = sights)"}, {"kampvuur", "campfire"}, {"raptordoder", "raptor slayer"} },
},

[587] = { en = "Up to Snuff", tier = 3,
  t = "Snuif op peil",
  d = "Ah, het leven op zee. Ik ga niet zeggen dat het het goede leven is, maar het is mijn leven.$b$bAls ik in de haven aankom, zoek ik graag een goede fles grog en wat snuif van hoge kwaliteit. Vieze gewoontes, maar wat is een piraat zonder zijn ondeugden, toch?$b$bDus je snapt wel hoe verdrietig ik was toen ik hoorde dat de kruidenkenner hier in de stad helemaal uitverkocht is. Hij zegt dat zijn lading is gekaapt door die vervloekte Bloodsail Raiders.$b$bIk wed dat een onbevreesde $c zoals jij ze kan overtuigen om de spullen te delen, hè?",
  o = "Deeg in Booty Bay wil dat je hem 15 porties Snuff brengt.",
  p = "Al geluk gehad met de spullen, maatje?",
  c = "Goed gedaan, $n! En net voordat ik weer moet uitvaren! Ik kan je niet genoeg bedanken, ouwe vriend.",
  g = { {"op peil", "up to standard (op peil)"}, {"snuif", "snuff (powdered tobacco)"}, {"haven", "port, harbour"}, {"gewoontes", "habits (gewoonte)"}, {"ondeugden", "vices (ondeugd)"}, {"kruidenkenner", "herbalist"}, {"uitverkocht", "sold out"}, {"lading", "shipment, cargo"}, {"gekaapt", "hijacked (kapen)"}, {"wed", "bet (wedden)"}, {"onbevreesde", "fearless (onbevreesd)"}, {"overtuigen", "to convince"}, {"porties", "portions, shares (portie)"}, {"maatje", "matey, buddy"}, {"uitvaren", "to ship out, to sail out"} },
},

[595] = { en = "The Bloodsail Buccaneers", tier = 3,
  t = "De Bloodsail Buccaneers",
  d = "Jij wilt echt graag aan het werk, maatje. Ik weet niet waarom een $r $c die van het land houdt de Blackwater Raiders wil helpen, maar ik ga je niet wegsturen.$b$bOns schip is net hier in Booty Bay aangemeerd. Het gerucht gaat dat onze rivalen, die vervloekte, smerige Bloodsail Buccaneers, overal in het zuiden van Stranglethorn zijn gezien.$b$bAlle jongens hebben het te druk met grog drinken en dames zoeken! Wat ik nodig heb, is een verkenner.$b$bBekijk de baai net ten noorden van Booty Bay, langs de Savage Coast, en kijk wat je vindt.",
  o = "First Mate Crazz wil dat je de baai ten noorden van Booty Bay bekijkt.",
  c = "Boven op het vat vind je een kaart met wat haastig geschreven tekst, en ook wat munten.",
  g = { {"wegsturen", "to send away, turn away"}, {"aangemeerd", "docked (aanmeren)"}, {"Het gerucht gaat", "word has it, rumour has it"}, {"rivalen", "rivals (rivaal)"}, {"smerige", "dirty (smerig)"}, {"verkenner", "scout"}, {"baai", "cove, bay"}, {"vat", "barrel"}, {"haastig", "hastily"}, {"munten", "coins (munt)"} },
},

[597] = { en = "The Bloodsail Buccaneers", tier = 3,
  t = "De Bloodsail Buccaneers",
  d = "De kaart laat Booty Bay zien, met een rode \"X\" precies op de plek waar je nu staat.$b$bDe gekrabbelde tekst zegt:$b$b\"Jullie mannen moeten op deze plek een kamp veiligstellen en stil blijven. Wacht op het signaal van de zuidelijke commandopost voordat jullie aanvallen. Als er iemand naar jullie toe komt, dood ze dan.\"",
  o = "Breng verslag uit over wat je hebt gevonden aan First Mate Crazz in Booty Bay.",
  c = "Natuurlijk herinner ik me jou, $c. Terug van het verkennen, zie ik...",
  g = { {"precies", "precisely, exactly"}, {"gekrabbelde", "scribbled (krabbelen)"}, {"veiligstellen", "to secure"}, {"signaal", "signal"}, {"commandopost", "command post"}, {"naar jullie toe komt", "approaches you (naar iemand toe komen)"}, {"Breng verslag uit", "report (verslag uitbrengen)"}, {"verkennen", "scouting, to scout"} },
},

[599] = { en = "The Bloodsail Buccaneers", tier = 3,
  t = "De Bloodsail Buccaneers",
  d = "Duizend bommen en granaten! Dus de Bloodsail Buccaneers plannen een soort aanval op Booty Bay? Wat een brutaliteit van die schurken! Booty Bay zal altijd in handen zijn van de Blackwater Raiders!$b$bDit is groter dan ik dacht. Vertel Fleet Master Seahorn meteen wat je te weten bent gekomen! De ouwe zeebonk is ergens in de stad...",
  o = "Meld de geplande aanval van de Bloodsail aan Fleet Master Seahorn.",
  c = "De Bloodsail Buccaneers die Booty Bay aanvallen? Dan kunnen ze zich net zo goed van de Overlook Cliffs gooien. Toch heb je mijn vloot van zeeschuimers een grote dienst bewezen door me dit nieuws te brengen. De Blackwater Raiders danken je.",
  g = { {"Duizend bommen en granaten", "shiver me timbers (a classic Dutch sailor's curse)"}, {"brutaliteit", "nerve, cheek"}, {"schurken", "scoundrels (schurk)"}, {"in handen", "in the hands (of), run by"}, {"te weten bent gekomen", "have learned (te weten komen)"}, {"zeebonk", "sea dog, old sailor"}, {"Meld", "report (melden)"}, {"net zo goed", "might as well"}, {"Toch", "nonetheless, still"}, {"vloot", "fleet"}, {"zeeschuimers", "swashbucklers, pirates (zeeschuimer)"}, {"een grote dienst bewezen", "done a great service (een dienst bewijzen)"} },
},

[600] = { en = "Venture Company Mining", tier = 3,
  t = "Mijnbouw van de Venture Company",
  d = "De Venture Company heeft een hele rij bedrijven in Stranglethorn. Daardoor kunnen hardwerkende goblins, zoals ik, geen eerlijk goud verdienen! Alsjeblieft, je moet me helpen!$B$BDe Venture Company graaft bij de Crystalvein Mine in het noorden. Ze kunnen de mijn niet in vanwege alle basilisken, maar ze kunnen nog wel Singing Crystals opgraven uit de heuvels eromheen.$B$BPak hun kristallen van ze af, en laat ze zien dat de jungle niet van hen is.$B$BEn... eh... breng me die kristallen als bewijs!",
  o = "Breng 10 Singing Blue Crystals naar Crank Fizzlebub in Booty Bay.",
  p = "Heb je die kristallen?? Ik heb ze nodig!!$B$BIk bedoel... ik moet weten dat de slechte Venture Company terrein verliest in Stranglethorn. Want, weet je, wij eerlijke mensen moeten ook de kost verdienen!",
  c = "Mooi! Geweldig! Ik kan hier een smak geld voor krijgen!!$B$BDie Venture Company heeft echt de verkeerde jungle uitgekozen om in te graven, hè? We zouden er allemaal beter voor staan als ze hier weggingen.$B$BBedankt, $N. Je hebt vandaag een goede daad verricht.",
  g = { {"Mijnbouw", "mining"}, {"rij", "row, string"}, {"hardwerkende", "hard-working"}, {"eerlijk", "honest"}, {"basilisken", "basilisks (basilisk)"}, {"opgraven", "to dig up"}, {"eromheen", "around it, surrounding"}, {"bewijs", "proof"}, {"terrein verliest", "is losing ground (terrein verliezen)"}, {"de kost verdienen", "to make a living"}, {"een smak geld", "a bundle, a pile of money"}, {"uitgekozen", "picked, chosen (uitkiezen)"}, {"er beter voor staan", "be in better shape"}, {"een goede daad verricht", "done a good deed"} },
},

[606] = { en = "Scaring Shaky", tier = 3,
  t = "Shaky bang maken",
  d = "Als ik ergens niet tegen kan, dan zijn het mensen die hun gokschulden niet betalen! En er zijn veel mensen die mij geld schuldig zijn. Denk je dat je me kunt helpen innen?$B$BEerst is er \"Shaky\" Phillipe, beneden bij de kades. Hij is me heel wat schuldig na het spel van vorige week, en ik wil krijgen wat me toekomt! Maar om dat te krijgen, moeten we hem bang maken.$B$BGa de stad uit en jaag op Elder Mistvale Gorillas. Zoek een mooie verzameling ingewanden en breng ze naar Shaky. Laat niet merken dat ze van een dier komen; laat hem maar het ergste denken.",
  o = "Breng 5 Mistvale Giblets naar \"Shaky\" Phillipe in Booty Bay.",
  p = "Hé! Ik vind het niet leuk hoe je naar me kijkt, $gmeneer:mevrouw;.",
  c = "Jakkes! Waar heb je die vandaan? Nee, zeg het niet. Ik wil het niet weten!$B$BWie heeft je gestuurd? Sea Wolf?",
  g = { {"ergens niet tegen kan", "can't stand something (ergens niet tegen kunnen)"}, {"gokschulden", "gambling debts (gokschuld)"}, {"schuldig", "owing (schuldig zijn = to owe)"}, {"innen", "to collect (money)"}, {"kades", "docks, quays (kade)"}, {"wat me toekomt", "what is due to me (toekomen)"}, {"jaag", "hunt (jagen)"}, {"verzameling", "selection, collection"}, {"ingewanden", "giblets, guts"}, {"Laat niet merken", "don't let on (laten merken)"}, {"het ergste", "the worst"}, {"Jakkes", "yuck, ugh"} },
},

[607] = { en = "Return to MacKinley", tier = 3,
  t = "Terug naar MacKinley",
  d = "Hier, neem dit buideltje en geef het aan Sea Wolf. En zeg hem dat ik van plan was hem terug te betalen! Ik zweer het!!$B$BIk was alleen een beetje dronken en raakte de weg kwijt, en... je weet hoe dat gaat. Hij zal het begrijpen. Je hoeft niet hardhandig te worden!",
  o = "Breng Shaky's Payment naar \"Sea Wolf\" MacKinley.",
  p = "Zo zo, $N. Heb je de betaling van Shaky gekregen?",
  c = "He he, goed gedaan! En toen je Shaky die ingewanden liet zien, hoe hard ging hij trillen?$B$BHa! Hij is zo makkelijk te lezen. Als ik met hem kaart, kan ik niet anders dan winnen!$B$BBedankt voor je hulp, $N. Nu is het jouw beurt om betaald te worden...",
  g = { {"buideltje", "little pouch (buidel)"}, {"van plan was", "meant to, intended to (van plan zijn)"}, {"terug te betalen", "to pay back (terugbetalen)"}, {"zweer", "swear (zweren)"}, {"dronken", "drunk"}, {"raakte de weg kwijt", "lost my way (de weg kwijtraken)"}, {"hardhandig", "rough, forceful"}, {"betaling", "payment"}, {"trillen", "to shake, to tremble"}, {"kaart", "play cards (kaarten)"}, {"niet anders dan", "can't help but"}, {"beurt", "turn"} },
},

[209] = { en = "Skullsplitter Tusks", tier = 3,
  t = "Slagtanden van de Skullsplitters",
  d = "Het is duur en moeilijk om genoeg tijgers te doden voor de export van tijgertanden naar de eilanden in de South Seas. Gelukkig hebben we een techniek ontwikkeld waarmee we gewone, hoornachtige voorwerpen kunnen veranderen in vervalsingen die niemand kan ontdekken.$b$bWat er het meest op lijkt, zijn verrassend genoeg de slagtanden van de Skullsplitter-trollen.$b$bHé, voordat je iets zegt: wat de koper niet weet, doet hem geen pijn, toch? Breng me er heel veel, zodat we aan de maandelijkse lading kunnen beginnen!",
  o = "Verzamel 18 Skullsplitter Tusks en breng ze terug naar Kebok.",
  p = "Taaie rakkers, hè? Nou, heb je al geluk gehad? Sorry dat ik ongeduldig lijk, maar dit is een enorme doorn in mijn oog! Nou?",
  c = "Ah, goed werk, goed werk! Bah, al had je ze wel wat beter schoon kunnen maken-- Nou ja, maakt niet uit, maakt niet uit! Mijn dank, $n. Dankzij jouw hulp zal onze onderneming ongetwijfeld meer opbrengen en productiever werken! Goed goed, en nu, op naar andere zaken...",
  g = { {"Slagtanden", "tusks (slagtand)"}, {"tijgertanden", "tiger fangs (tijgertand)"}, {"ontwikkeld", "developed (ontwikkelen)"}, {"hoornachtige", "horn-like"}, {"vervalsingen", "forgeries (vervalsing)"}, {"ontdekken", "to detect, to discover"}, {"Wat er het meest op lijkt", "the closest match (lijken op = to look like)"}, {"verrassend genoeg", "amazingly, surprisingly"}, {"koper", "buyer"}, {"maandelijkse", "monthly"}, {"Taaie rakkers", "tough buggers (taai = tough)"}, {"ongeduldig", "impatient"}, {"een enorme doorn in mijn oog", "a huge thorn in my side"}, {"onderneming", "operation, business"}, {"ongetwijfeld", "no doubt, undoubtedly"}, {"opbrengen", "to yield, to produce"} },
},

[576] = { en = "Keep An Eye Out", tier = 3,
  t = "Houd een oogje in het zeil",
  d = "Halt! Wie is daar?$b$bArgh, ik ben nutteloos zonder mijn speciale betoverde oog. Erg genoeg dat ik mijn ogen in de strijd ben kwijtgeraakt! Maar door een gelukje meerden we aan in Menethil, en een rondreizende tovenaar betoverde een speciaal glazen oog waarmee ik weer kon zien.$b$bGisteravond werd ik op weg naar buiten overvallen door een paar Bloodsail Buccaneers. Ze hebben mijn oog meegenomen! Die kerels hebben blijkbaar de weg naar Booty Bay gevonden.$b$bWil je een ouwe zeebonk helpen door mijn oog terug te halen?",
  o = "Dizzy One-Eye in Booty Bay wil dat je zijn oog terughaalt bij de Bloodsail Buccaneers.",
  p = "Ahoi, maatje! Ik kan misschien niet zien, maar ik ruik je van halverwege de haven.$b$bIk zou mijn oog echt graag terug hebben. De kapitein gaat me kielhalen als hij hoort dat mijn kijker in handen is van die smerige Bloodsail Buccaneers.$b$bWat heb je aan een uitkijk die niet kan zien? Het kraaiennest was vroeger mijn thuis... zonder mijn kijkers mag ik blij zijn als ik het ruim mag schrobben.",
  c = "Duizend bommen en granaten, en granaten en bommen! Je hebt mijn mooie oog gevonden! Eens kijken of ze nog past.$b$b$n in zicht! Allemachtig, ik kan zien!!",
  g = { {"een oogje in het zeil", "keep an eye out (een oogje in het zeil houden)"}, {"nutteloos", "useless"}, {"betoverde", "enchanted (betoveren)"}, {"kwijtgeraakt", "lost (kwijtraken)"}, {"door een gelukje", "by a stroke of luck"}, {"meerden we aan", "we docked (aanmeren)"}, {"rondreizende", "traveling"}, {"overvallen", "jumped, attacked"}, {"kerels", "blokes, guys (kerel)"}, {"halverwege", "halfway"}, {"kielhalen", "to keelhaul"}, {"kijker", "peeper, eye (also: binoculars)"}, {"uitkijk", "lookout"}, {"kraaiennest", "crow's nest"}, {"ruim", "ship's hold, bilge"}, {"schrobben", "to scrub"}, {"Allemachtig", "blimey, good heavens"} },
},

[197] = { en = "Raptor Mastery", tier = 3,
  t = "Meester van de raptors",
  d = "Je hebt bewezen dat je in de jungle echt van aanpakken weet. Daarom vertel ik je over een woeste raptor die zelfs ik niet heb kunnen doden. Ajeck hier noemt deze sluwe raptor Tethis.$b$bAls je wilt bewijzen dat je een echte meester bent, dood dan Tethis en breng me zijn klauw. Het zou een prestatie zijn die nog geen enkele andere grootwildjager heeft geleverd.",
  o = "Hemet Nesingwary wil dat je Tethis doodt, een ongrijpbare, gevaarlijke raptor in Stranglethorn.",
  p = "Hoe gaat de jacht op Tethis? Ben je haar helemaal tot in het kamp gevolgd, of wat?",
  c = "Meester $N, de raptordoder!$b$bKlinkt goed, hè?",
  g = { {"bewezen", "proved (bewijzen)"}, {"van aanpakken weet", "is a go-getter (van aanpakken weten)"}, {"woeste", "ferocious (woest)"}, {"sluwe", "wily, sly (sluw)"}, {"klauw", "talon, claw"}, {"prestatie", "feat, achievement"}, {"geleverd", "accomplished (een prestatie leveren)"}, {"ongrijpbare", "elusive (ongrijpbaar)"}, {"gevolgd", "tracked, followed (volgen)"}, {"raptordoder", "raptor slayer"} },
},

[208] = { en = "Big Game Hunter", tier = 3,
  t = "Grootwildjager",
  d = "$N, jij bent een jager die ons gezelschap waardig is. Van de slagvelden van Lordaeron tot de diepste jungle heb ik zelden zoveel vaardigheid met wapens gezien als jij hebt laten zien.$b$bJe hebt de woeste Sin'Dall gedood, de ongrijpbare Bag'thera en de verraderlijke Tethis. Maar de echte prijs is de kop van King Bangalash. Die witte tijger is de reden dat ik hier ben. Ik heb hem al een hele tijd in het vizier. Dood King Bangalash, dan is bewezen dat niemand zo goed kan jagen als jij.",
  o = "Hemet Nesingwary wil dat je hem de kop van King Bangalash brengt, de grote witte tijger.",
  p = "Ik zie dat je terug bent, ouwe kerel. King Bangalash heeft mij al vaak terug naar het kamp laten kruipen. Hou vol.",
  c = "Verdraaid goed gedaan! Prima! Gefeliciteerd, $N, omdat het jou is gelukt waar anderen faalden.$B$BIk vind het een eer om jou een kameraad te noemen van ons grote jachtgezelschap hier. Niemand zal ooit twijfelen aan jouw kennis van jagen en sporen zoeken!$B$BProost op jou, zeg ik! Proost!",
  g = { {"Grootwildjager", "big game hunter"}, {"gezelschap", "company, party"}, {"waardig", "worthy (of)"}, {"slagvelden", "battlefields (slagveld)"}, {"zelden", "rarely"}, {"vaardigheid", "skill, prowess"}, {"verraderlijke", "treacherous (verraderlijk)"}, {"kop", "head (of an animal)"}, {"in het vizier", "in my sights"}, {"kruipen", "to crawl"}, {"Hou vol", "hang in there (volhouden)"}, {"Verdraaid", "bloody, darned (mild curse)"}, {"faalden", "failed (falen)"}, {"kameraad", "comrade"}, {"jachtgezelschap", "hunting party"}, {"sporen zoeken", "tracking (spoor = track)"} },
},

[604] = { en = "The Bloodsail Buccaneers", tier = 3,
  t = "De Bloodsail Buccaneers",
  d = "Crazz is vol lof over jouw inzet voor de Blackwater Raiders. Ik ga je een missie toevertrouwen die heel belangrijk is voor de vloot.$b$bDring binnen in de zogenaamde zuidelijke commandopost die de Bloodsail Buccaneers aan de Wild Shore hebben opgezet. Overval het kamp. Breng me hun zeekaarten en hun geschreven bevelen. Dan zien we precies wat dat tuig van plan is.",
  o = "Fleet Master Seahorn in Booty Bay wil dat je 10 Bloodsail Swashbucklers doodt en de Bloodsail Charts en de Bloodsail Orders terugbrengt.",
  p = "Ahoi, $n. Wat voor nieuws breng je over het kamp van de Bloodsail in het zuiden?",
  c = "Perfect, $n. Nu we hun plan kennen, is het nog maar een kwestie van tijd.$b$bEn te bedenken dat die dwazen vlak voor de kaap het anker hebben uitgegooid...",
  g = { {"vol lof over", "speaks highly of (lof = praise)"}, {"inzet", "dedication, effort"}, {"toevertrouwen", "to entrust (with)"}, {"Dring binnen", "infiltrate, break in (binnendringen)"}, {"zogenaamde", "so-called"}, {"opgezet", "set up, established (opzetten)"}, {"Overval", "raid (overvallen)"}, {"zeekaarten", "sea charts (zeekaart)"}, {"bevelen", "orders (bevel)"}, {"tuig", "scum, rabble"}, {"kwestie", "matter, question"}, {"te bedenken", "to think (bedenken)"}, {"dwazen", "fools (dwaas)"}, {"kaap", "cape"}, {"het anker hebben uitgegooid", "have dropped anchor (het anker uitgooien)"} },
},

[617] = { en = "Akiris by the Bundle", tier = 3,
  t = "Akiris per bundel",
  d = "Zoek je werk, $N? Misschien heb ik wat voor je, als je zin hebt in een kleine uitdaging.$B$BIk heb een vriend die Groy heet. Hij verdient een fortuin met de verkoop van wat de naga akirisriet noemen: het is een soort waardevol zeeriet. Ik weet niet precies waar het voor is, maar hij betaalt goed voor bundels van dat spul.$B$BBreng jij me tien stengels van dat spul, dan kunnen we zaken doen. De naga zijn het laatst gezien langs het strand ten noorden van hier.",
  o = "Breng 10 Bundles of Akiris Reed naar Privateer Bloads in Booty Bay.",
  p = "Als je niks met mij te maken hebt, loop dan door, $N.",
  c = "Goed gedaan, $N. Tien stengels akirisriet was toch niet zo'n grote uitdaging, hè? Niks tegen de naga, maar hé, iedereen moet de kost verdienen.",
  g = { {"bundel", "bundle"}, {"zin hebt in", "are up for, feel like (zin hebben in)"}, {"verdient een fortuin", "makes a killing (een fortuin verdienen)"}, {"akirisriet", "akiris reed (riet = reed)"}, {"waardevol", "valuable"}, {"zeeriet", "ocean reed"}, {"spul", "stuff"}, {"stengels", "stalks (stengel)"}, {"zaken doen", "to do business"}, {"loop dan door", "then move along (doorlopen)"}, {"Niks tegen", "no offense to"}, {"de kost verdienen", "to make a living"} },
},

[623] = { en = "Akiris by the Bundle", tier = 3,
  t = "Akiris per bundel",
  d = "$N, nu ik je hier toch heb: ik kreeg een bericht van Groy terwijl je weg was. Hij zei dat hij tevreden was met de laatste lading die aankwam, en hij heeft een klant die meteen meer van dat spul wil.$B$BIk ga pas over een week naar Theramore, maar als jij de reis wilt maken, is er geen reden waarom jij het spul niet voor me kunt brengen.$B$BZin in avontuur? Je weet toch waar Dustwallow Marsh is? Ik zou wel voorzichtig zijn, hoor. Theramore kan gevaarlijk zijn als je bij het verkeerde soort volk hoort.",
  o = "Breng een Bundle of Akiris Reeds naar Privateer Groy in Theramore.",
  p = "Ja?",
