[609] = { en = "Voodoo Dues", tier = 3,
  t = "Voodooschulden",
  d = "Mijn lijst wordt korter, maar er zijn nog steeds mensen die mij iets schuldig zijn.$B$BDe volgende zijn Maury \"Club Foot\" Wilkins, Jon-Jon the Crow en Chucky \"Ten Thumbs\".$B$BDe schulden van deze schurftige honden staan al maanden open, en ik dacht dat ze de stad uit waren gevlucht om niet te hoeven betalen! Later hoorde ik dat ze vervloekt en betoverd zijn en nu door de ruïnes in de jungle dwalen. Maar het kan me niet schelen wat er met ze is gebeurd. Ik wil wat van mij is!$B$BZe zijn bij de Ruins of Aboraz en de Ruins of Jubuwal, ten noordoosten van hier. Zoek ze op en int hun schuld.",
  o = "Breng Maury's Clubbed Foot, Jon-Jon's Golden Spyglass en Chucky's Huge Ring naar \"Sea Wolf\" MacKinley in Booty Bay.",
  p = "$N, heb je die drie honden gevonden? Heb je hun waardevolle spullen opgehaald?",
  c = "Geweldig! Hier krijg ik een goede prijs voor, vooral voor wat er in Maury's voet zit! Heel erg bedankt, $N!$B$BIk hoop dat die drie hun lesje hebben geleerd: wed nooit iets wat je je niet kunt veroorloven om te verliezen.$B$BEn misschien is het voor hen te laat, maar... ze zouden beter moeten opletten met wie ze gokken.",
  g = { {"Voodooschulden", "voodoo debts (schuld = debt)"}, {"schurftige", "scurvy, mangy (schurftig)"}, {"staan al maanden open", "have been outstanding for months (openstaan)"}, {"gevlucht", "fled, skipped (vluchten)"}, {"vervloekt", "cursed"}, {"betoverd", "bewitched"}, {"dwalen", "wander"}, {"het kan me niet schelen", "I don't care"}, {"int", "collect (innen)"}, {"waardevolle", "valuable"}, {"lesje", "lesson"}, {"wed", "bet (wedden)"}, {"veroorloven", "to afford"}, {"opletten", "to watch out, be careful"}, {"gokken", "to gamble"} },
},

[613] = { en = "Cracking Maury's Foot", tier = 3,
  t = "Maury's voet openbreken",
  d = "Verdorie! Die sukkel Maury heeft een slot op zijn voet gezet, en ik krijg hem niet open! Zijn buit zit in die voet, en dat is wat hij me schuldig is!$B$BWe moeten de sleutel vinden om het slot te openen. Maury gokte vaak met de Mosh'Ogg-ogers, bij hun heuvel in het noordoosten. En toen hij nog leefde, vertelde hij me dat hij de laatste keer bij de heuvel werd weggejaagd omdat hij te veel won. Misschien hebben de ogers daar zijn sleutel.$B$BMaar als dat zo is, moet je er misschien heel wat doden om de juiste te vinden...",
  o = "Breng Maury's Key naar \"Sea Wolf\" Mackinley in Booty Bay.",
  p = "Ahoi, $N! Heb je de sleutel van Maury al gevonden?",
  c = "Je hebt hem gevonden! Duizendmaal dank, $N. Je hebt me enorm geholpen!$b$bAlsjeblieft, dit heb je verdiend!",
  g = { {"openbreken", "to crack open, break open"}, {"Verdorie", "curses, darn"}, {"sukkel", "fool, swab"}, {"slot", "lock"}, {"buit", "loot"}, {"gokte", "gambled (gokken)"}, {"ogers", "ogres (oger)"}, {"heuvel", "mound, hill"}, {"weggejaagd", "chased off (wegjagen)"}, {"juiste", "right one (juist)"}, {"Duizendmaal dank", "thanks a million"}, {"verdiend", "earned (verdienen)"} },
},

[621] = { en = "Zanzil's Secret", tier = 3,
  t = "Het geheim van Zanzil",
  d = "Zanzil the Outcast woont met zijn volgelingen in de ruïnes van Jubuwai en Aboraz, ten noordoosten van Booty Bay. Hij is verbannen uit zijn stam. Waarom? Nou...$B$BZanzil kent manieren om de geest van anderen te buigen, en zijn leiders zijn bang voor hem. Hij gebruikt een mengsel van jungleplanten op zijn volgelingen om hun wil te onderdrukken en hun lichaam sterker te maken.$B$BZijn mengsel zou veel waard zijn voor wie anderen wil beheersen.$B$BBreng me monsters van zijn mengsel, dan vind ik er wel een toepassing voor.",
